import { useState } from 'react'

function App() {
  const [count, setCount] = useState(0)

  return (
    <main className="app">
      <h1>React + Vite</h1>
      <button onClick={() => setCount((v) => v + 1)}>Count is {count}</button>
    </main>
  )
}

export default App

